//! Auto-generated navigation page (openwiki's quickstart/index analog).
//! Index is derived state: regenerated on demand, never cited, excluded from
//! planning so it cannot generate its own refresh tasks.

use std::collections::BTreeMap;
use std::path::Path;

use wiki_core::{parse_wiki_links, Status, WikiPage};
use wiki_git::GitRepo;

use crate::{check_page, load_pages, now_iso, pages_dir, Result};

pub const INDEX_ID: &str = "index";

/// Build index.md content grouped by top-level directory (or "top level"),
/// each line linking the page with live git freshness, never a plain text dump.
pub fn generate_index(repo: &GitRepo, wiki_dir: &Path) -> Result<WikiPage> {
    let pages = load_pages(wiki_dir)?;
    let mut groups: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut stale_count = 0usize;
    for p in pages.iter().filter(|p| p.meta.id != INDEX_ID) {
        let live_stale = check_page(p, repo).map(|r| r.is_stale).unwrap_or(false);
        if live_stale {
            stale_count += 1;
        }
        let group = match p.meta.id.split_once('/') {
            Some((head, _)) => head.to_string(),
            None => ".".to_string(),
        };
        let status = match (p.meta.status, live_stale) {
            (Status::Verified, false) => "verified",
            (_, true) => "STALE",
            (Status::Draft, _) => "draft",
            (Status::Stale, _) => "stale",
        };
        groups.entry(group).or_default().push(format!(
            "- [[wiki:{}]] — {} _( {}, {} evidence, type: {} )_",
            p.meta.id,
            p.meta.title,
            status,
            p.meta.evidence.len(),
            p.meta.page_type.as_deref().unwrap_or("-")
        ));
    }
    let mut body = String::from("# Repository wiki index\n\nGenerated by `repowiki index`. Navigation only, not evidence-backed.\n\n");
    for (group, lines) in groups {
        body.push_str(&format!("## {group}\n\n{}\n\n", lines.join("\n")));
    }
    body.push_str(&format!(
        "_{} page(s), {stale_count} stale, generated {}_\n",
        pages.iter().filter(|p| p.meta.id != INDEX_ID).count(),
        now_iso()
    ));
    let page = WikiPage {
        meta: wiki_core::PageMeta {
            id: INDEX_ID.into(),
            title: "Wiki index".into(),
            status: Status::Verified,
            generated_at: now_iso(),
            commit: repo.head_commit()?,
            evidence: vec![],
            tags: vec!["generated".into()],
            page_type: Some("index".into()),
        },
        body,
        source_path: Some(pages_dir(wiki_dir).join(format!("{INDEX_ID}.md"))),
    };
    page.save_in_place()?;
    Ok(page)
}

/// Collect all [[wiki:id]] targets across pages (for lint).
pub fn all_wiki_links(wiki_dir: &Path) -> Result<Vec<(String, String)>> {
    let mut out = Vec::new();
    for p in load_pages(wiki_dir)? {
        for target in parse_wiki_links(&p.body) {
            out.push((p.meta.id.clone(), target));
        }
    }
    Ok(out)
}
